<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entitlements · EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f5f7fb;color:#172033}main{max-width:1200px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:12px;border-bottom:1px solid #eee}.muted{color:#667085}.pill{padding:4px 8px;border-radius:99px;background:#eef2ff}</style></head><body><main><h1>Plans & Features</h1><p class="muted">Configure packages from database data. Nothing here depends on hard-coded Starter/Standard/Enterprise rules.</p><section class="grid"><?php foreach($plans as $p): ?><a class="card" href="/platform/plans/<?= (int)$p['id'] ?>" style="text-decoration:none;color:inherit"><h2><?= htmlspecialchars((string)$p['name']) ?></h2><p class="muted"><?= htmlspecialchars((string)($p['description']??'')) ?></p><strong><?= (int)$p['feature_count'] ?> features</strong><div class="muted"><?= htmlspecialchars((string)$p['billing_interval']) ?> · <?= htmlspecialchars((string)$p['price']) ?></div></a><?php endforeach; ?></section><div class="card" style="margin-top:22px"><h2>Feature catalog</h2><table><thead><tr><th>Module</th><th>Feature</th><th>Code</th><th>Status</th></tr></thead><tbody><?php foreach($features as $f): ?><tr><td><span class="pill"><?= htmlspecialchars((string)$f['module_code']) ?></span></td><td><?= htmlspecialchars((string)$f['name']) ?></td><td><?= htmlspecialchars((string)$f['code']) ?></td><td><?= !empty($f['is_active'])?'Active':'Inactive' ?></td></tr><?php endforeach; ?></tbody></table></div></main></body></html>
